index.html:
/* Public module identity accents: unassessed items only. */
html[data-qs-staff-entry="0"] #overview-face:not([class*="state-"]) .public-module-icon,html[data-qs-staff-entry="0"] #row-face:not([class*="state-"]) .module-icon{color:#0D9488;background-color:#F0FDFA}
html[data-qs-staff-entry="0"] #overview-arm:not([class*="state-"]) .public-module-icon,html[data-qs-staff-entry="0"] #row-arm:not([class*="state-"]) .module-icon{color:#2563EB;background-color:#EFF6FF}
html[data-qs-staff-entry="0"] #overview-speech:not([class*="state-"]) .public-module-icon,html[data-qs-staff-entry="0"] #row-speech:not([class*="state-"]) .module-icon{color:#7C3AED;background-color:#F5F3FF}

assets/public-result.css:
/* Public module identity accent; no clinical or layout changes. */
html[data-result-public="1"] body:has(#summary-card.ok) #module-grid .module-tile.ok:nth-child(1) .module-icon{color:#0D9488!important;background-color:#F0FDFA!important}
html[data-result-public="1"] body:has(#summary-card.ok) #module-grid .module-tile.ok:nth-child(2) .module-icon{color:#2563EB!important;background-color:#EFF6FF!important}
html[data-result-public="1"] body:has(#summary-card.ok) #module-grid .module-tile.ok:nth-child(3) .module-icon{color:#7C3AED!important;background-color:#F5F3FF!important}

